import os
import json
from flask import Flask, request, jsonify, Response, stream_with_context, send_file
from flask_cors import CORS
from anthropic import Anthropic

app = Flask(__name__)
CORS(app)

MODEL = "claude-opus-4-7"
MAX_TOKENS = 128000


def get_client():
    return Anthropic(
        api_key=os.environ["ANTHROPIC_API_KEY"],
        default_headers={
            "anthropic-workspace-id": os.environ["ANTHROPIC_WORKSPACE_ID"]
        },
    )


@app.route("/")
def index():
    response = send_file("index.html")
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    response.headers["Pragma"] = "no-cache"
    response.headers["Expires"] = "0"
    return response


@app.route("/api/chat", methods=["POST"])
def chat():
    data = request.get_json(force=True)
    messages = data.get("messages", [])
    system_prompt = data.get("system", "")

    if not messages:
        return jsonify({"error": "No messages provided"}), 400

    anthropic_messages = []
    for msg in messages:
        role = msg.get("role")
        content = msg.get("content", "")
        if role in ("user", "assistant") and content:
            anthropic_messages.append({"role": role, "content": content})

    if not anthropic_messages:
        return jsonify({"error": "No valid messages provided"}), 400

    def generate():
        client = get_client()
        kwargs = {
            "model": MODEL,
            "max_tokens": MAX_TOKENS,
            "messages": anthropic_messages,
        }
        if system_prompt:
            kwargs["system"] = system_prompt

        with client.messages.stream(**kwargs) as stream:
            for text in stream.text_stream:
                chunk = json.dumps({"type": "text", "text": text})
                yield f"data: {chunk}\n\n"
            final_message = stream.get_final_message()
            usage = {
                "input_tokens": final_message.usage.input_tokens,
                "output_tokens": final_message.usage.output_tokens,
            }
            stop_reason = final_message.stop_reason
            done_chunk = json.dumps(
                {"type": "done", "usage": usage, "stop_reason": stop_reason}
            )
            yield f"data: {done_chunk}\n\n"

    return Response(
        stream_with_context(generate()),
        mimetype="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
            "Connection": "keep-alive",
        },
    )


@app.route("/api/health", methods=["GET"])
def health():
    return jsonify({"status": "ok", "model": MODEL, "max_tokens": MAX_TOKENS})


if __name__ == "__main__":
    port = int(os.environ.get("PORT", 5000))
    app.run(host="0.0.0.0", port=port, debug=False)






